const fetchJson=async(url,body)=>{const r=await fetch(url,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});const j=await r.json();if(!r.ok)throw Error(j.error||'服务未响应');return j};
export async function mountFeishu(parent=document.querySelector('#workspaceBody')){const host=document.createElement('section');host.className='work-card';host.innerHTML='<h2>飞书 Agent 与定时报告</h2><p class="fs-state">检查连接…</p><p>私聊提问、指定品种研究、后台完成通知。只回应本机授权名单内的用户；群聊需额外授权并@机器人。</p><form><label><input type="checkbox" name="enabled"> 启用定时推送</label> <label>北京时间 <input name="times" value="15:30,21:00" aria-label="飞书推送时间"></label> <button class="quiet">保存计划</button></form><p>仅核验后的交易日推送；本机工作台须运行。睡眠或关机期间不执行，错过5分钟不补发。</p><div><button class="quiet fs-preview">预览报告</button> <button class="quiet fs-push">立即发送到已配置目标</button></div><p class="fs-result" role="status"></p><details><summary>首次配置</summary><p>优先到“设置”点击“飞书扫码绑定”；若组织不支持一键流程，再创建飞书企业自建应用，启用机器人与长连接，订阅 im.message.receive_v1 并开通收发消息权限。发布版本后，在项目目录双击“配置飞书机器人.command”，隐藏填写 App Secret，并填写本人 Open ID 与推送目标。重新打开工作台。</p><p>密钥留在本机.env，不发到聊天、不提交GitHub。尚未配置时，只能本地预览。</p></details><pre class="fs-output" style="white-space:pre-wrap;max-height:520px;overflow:auto"></pre>';parent.prepend(host);const state=host.querySelector('.fs-state'),result=host.querySelector('.fs-result'),form=host.querySelector('form'),push=host.querySelector('.fs-push');
const update=async()=>{const s=await fetchJson('/api/feishu/status');if(!host.isConnected)return;state.textContent=`应用：${s.configured?'已配置':'未配置'} · 长连接：${s.transport} · 推送：${s.enabled?'已启用':'未启用'}${s.lastError?' · '+s.lastError:''}`;form.elements.enabled.checked=s.enabled;form.elements.times.value=s.times.join(',');push.disabled=!s.targetConfigured||!s.ready};
form.onsubmit=async e=>{e.preventDefault();try{await fetchJson('/api/feishu/schedule',{enabled:form.elements.enabled.checked,times:form.elements.times.value.split(',').map(s=>s.trim())});result.textContent='计划已保存';await update()}catch(e){result.textContent=e.message}};
host.querySelector('.fs-preview').onclick=async()=>{try{const r=await fetchJson('/api/feishu/preview');host.querySelector('.fs-output').textContent=r.text;result.textContent='本地预览，尚未发送'}catch(e){result.textContent=e.message}};
push.onclick=async()=>{push.disabled=true;try{const r=await fetchJson('/api/feishu/push',{});result.textContent=r.sent?'飞书已确认发送':'本分钟已处理，未重复发送'}catch(e){result.textContent=e.message}finally{await update().catch(()=>{})}};
try{await update()}catch(e){state.textContent=e.message}}
export async function mountThreeAxes(){const host=document.createElement('section');host.className='work-card';host.innerHTML='<h2>三板斧 · 独立参考筛选</h2><p>读取TqSdk实际合约与完成K线。多周期共振和1.5×ATR是外部研究参考，不替代五简五道门，不假设账户权益。</p><p role="status">正在计算…</p><details><summary>查看八段式复盘</summary><pre style="white-space:pre-wrap"></pre></details>';document.querySelector('#workspaceBody').prepend(host);try{const r=await fetchJson('/api/three-axes');if(!host.isConnected)return;host.querySelector('[role=status]').textContent=`${r.coverage.retained}个真实合约 · 多头共振 ${r.counts.long} · 空头共振 ${r.counts.short} · 不共振 ${r.counts.flat} · 历史不足 ${r.counts.unknown} · ${r.status}`;host.querySelector('pre').textContent=r.text}catch(e){host.querySelector('[role=status]').textContent=e.message}}
